package me.bedwarshurts.leagueproximitychat.position;

import me.bedwarshurts.leagueproximitychat.utils.LeagueConfigReader;
import me.bedwarshurts.leagueproximitychat.utils.RitoApiUtils;
import me.bedwarshurts.leagueproximitychat.utils.WindowUtils;
import org.opencv.core.*;
import org.opencv.core.Point;
import org.opencv.highgui.HighGui;
import org.opencv.imgcodecs.Imgcodecs;
import org.opencv.imgproc.Imgproc;
import org.opencv.imgproc.Moments;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferByte;

public class HybridPositionTracker {

    private Robot robot;
    private float userMinimapScale;

    private Mat championTemplate;
    private Mat calibratedTemplate = null;

    private Point lastKnownCenter = null;

    private static final float SCREEN_TO_MAP_RATIO = 0.05f;

    public static class TrackResult {
        public float x;
        public float y;
        public boolean isDead;

        public TrackResult(float x, float y, boolean isDead) {
            this.x = x;
            this.y = y;
            this.isDead = isDead;
        }
    }

    public HybridPositionTracker() {
        try {
            this.robot = new Robot();

            LeagueConfigReader.LeagueSettings settings = LeagueConfigReader.loadSettings();
            this.userMinimapScale = settings.minimapScale;

            this.championTemplate = AutoTemplateLoader.autoLoadChampionTemplate();
            if (championTemplate != null) {
                HighGui.imshow("Champion Template", championTemplate);
                HighGui.waitKey(0);

                Imgcodecs.imwrite("debug_template.png", championTemplate);
                warnIfTemplateIsFlat(championTemplate);
            }

            if (this.championTemplate == null) {
                System.err.println("[TRACKER] CRITICAL: Failed to load champion template.");
            }

        } catch (AWTException e) {
            System.err.println("[TRACKER] Failed to initialize Java Robot API");
            e.printStackTrace();
        }
    }

    public TrackResult trackPlayerPosition() {
        boolean isDead = checkDeathState();

        java.awt.Rectangle gameBounds = WindowUtils.getGameWindowBounds("League of Legends (TM) Client");

        if (gameBounds == null) {
            return new TrackResult(50f, 50f, isDead);
        }

        double baseMapPercent = 0.1425;
        int perfectMapSize = (int) (gameBounds.height * baseMapPercent * userMinimapScale);

        java.awt.Rectangle minimapBounds = new java.awt.Rectangle(
                gameBounds.x + gameBounds.width - perfectMapSize,
                gameBounds.y + gameBounds.height - perfectMapSize,
                perfectMapSize,
                perfectMapSize
        );

        Mat fullScreenMat = captureScreen(gameBounds);
        Mat minimapMat = captureScreen(minimapBounds);

        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_screen.png", fullScreenMat);
            Imgcodecs.imwrite("debug_minimap.png", minimapMat);
        }

        Point healthBarCenter = locateSelfHealthBar(fullScreenMat);

        if (healthBarCenter != null) {
            float offsetX = (float) (healthBarCenter.x - (gameBounds.width / 2.0));
            float offsetY = (float) (healthBarCenter.y - (gameBounds.height / 2.0));

            Point cameraMapCenter = locateMinimapCameraBox(minimapMat);

            float finalX = (float) cameraMapCenter.x + (offsetX * SCREEN_TO_MAP_RATIO);
            float finalY = (float) cameraMapCenter.y + (offsetY * SCREEN_TO_MAP_RATIO);

            float invertedY = 100f - ((finalY / minimapBounds.height) * 100f);

            return new TrackResult((finalX / minimapBounds.width) * 100f, invertedY, isDead);

        } else if (championTemplate != null) {
            Point champMapCenter = locateChampionViaTemplate(minimapMat);

            if (champMapCenter != null) {
                float finalX = (float) champMapCenter.x;
                float finalY = (float) champMapCenter.y;

                float invertedY = 100f - ((finalY / minimapBounds.height) * 100f);

                return new TrackResult((finalX / minimapBounds.width) * 100f, invertedY, isDead);
            }
        }

        return new TrackResult(50f, 50f, isDead);
    }

    private boolean checkDeathState() {
        String localSummonerName = RitoApiUtils.getLocalSummonerName();

        if (localSummonerName != null) {
            String playerListJson = RitoApiUtils.fetchAPI("https://127.0.0.1:2999/liveclientdata/playerlist");
            if (playerListJson != null) {
                int nameIdx = playerListJson.indexOf("\"" + localSummonerName + "\"");
                if (nameIdx != -1) {
                    int blockStart = playerListJson.lastIndexOf("\"championName\":", nameIdx);
                    if (blockStart != -1) {
                        int blockEnd = playerListJson.indexOf("\"championName\":", blockStart + 15);
                        if (blockEnd == -1) {
                            blockEnd = playerListJson.length();
                        }

                        String playerBlock = playerListJson.substring(blockStart, blockEnd).replaceAll("\\s+", "");
                        return playerBlock.contains("\"isDead\":true");
                    }
                }
            }
        }
        return false;
    }

    private Point locateSelfHealthBar(Mat screen) {
        Mat hsv = new Mat();
        Imgproc.cvtColor(screen, hsv, Imgproc.COLOR_BGR2HSV);

        Scalar lowerYellow = new Scalar(22, 140, 200);
        Scalar upperYellow = new Scalar(26, 255, 255);

        Mat mask = new Mat();
        Core.inRange(hsv, lowerYellow, upperYellow, mask);

        int hudTopY = (int) (screen.height() * 0.75);
        Imgproc.rectangle(mask, new Point(0, hudTopY), new Point(screen.width(), screen.height()), new Scalar(0), -1);

        Imgproc.rectangle(mask, new Point(screen.width() * 0.85, 0), new Point(screen.width(), screen.height() * 0.10), new Scalar(0), -1);

        Mat openKernel = Imgproc.getStructuringElement(Imgproc.MORPH_RECT, new org.opencv.core.Size(3, 3));
        Imgproc.morphologyEx(mask, mask, Imgproc.MORPH_OPEN, openKernel);
        openKernel.release();

        Mat closeKernel = Imgproc.getStructuringElement(Imgproc.MORPH_RECT, new org.opencv.core.Size(11, 1));
        Imgproc.morphologyEx(mask, mask, Imgproc.MORPH_CLOSE, closeKernel);
        closeKernel.release();

        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_health_mask.png", mask);
        }

        java.util.List<MatOfPoint> contours = new java.util.ArrayList<>();
        Mat hierarchy = new Mat();
        Imgproc.findContours(mask, contours, hierarchy, Imgproc.RETR_EXTERNAL, Imgproc.CHAIN_APPROX_SIMPLE);

        Rect bestBar = null;
        double bestDistance = Double.MAX_VALUE;

        double minHeight = screen.height() * 0.003;
        double maxHeight = screen.height() * 0.020;
        double minWidth = screen.width() * 0.008;

        for (MatOfPoint contour : contours) {
            Rect rect = Imgproc.boundingRect(contour);
            double pixelArea = Imgproc.contourArea(contour);

            if (rect.height >= minHeight && rect.height <= maxHeight && rect.width >= minWidth) {

                double extent = pixelArea / (double) (rect.width * rect.height);
                double aspectRatio = rect.width / (double) rect.height;

                if (extent > 0.75 && aspectRatio > 2.5) {

                    double centerX = rect.x + (rect.width / 2.0);
                    double centerY = rect.y + (rect.height / 2.0);

                    double distToCenter = Math.pow(centerX - (screen.width() / 2.0), 2) + Math.pow(centerY - (screen.height() / 2.0), 2);

                    if (distToCenter < bestDistance) {
                        bestDistance = distToCenter;
                        bestBar = rect;
                    }
                }
            }
        }

        if (bestBar != null) {
            return new Point(bestBar.x + (bestBar.width / 2.0), bestBar.y + (bestBar.height / 2.0));
        }

        return null;
    }

    private Point locateMinimapCameraBox(Mat minimap) {
        Mat gray = new Mat();
        Imgproc.cvtColor(minimap, gray, Imgproc.COLOR_BGR2GRAY);

        Mat thresholded = new Mat();
        Imgproc.threshold(gray, thresholded, 240, 255, Imgproc.THRESH_BINARY);

        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_camera_mask.png", thresholded);
        }

        Moments moments = Imgproc.moments(thresholded);
        if (moments.get_m00() > 0) {
            int x = (int) (moments.get_m10() / moments.get_m00());
            int y = (int) (moments.get_m01() / moments.get_m00());
            return new Point(x, y);
        }
        return new Point(minimap.width() / 2.0, minimap.height() / 2.0);
    }


    private Point locateChampionViaTemplate(Mat minimap) {
        System.out.println("[TRACKER] Primary HP bar lost. Running Stateful ROI Tracker...");

        // GLOBAL is very strict to prevent locking onto mud.
        // LOCAL is extremely loose to survive Viego sitting on top of her.
        double GLOBAL_ACQUIRE_THRESHOLD = 0.55;
        double GLOBAL_REACQUIRE_STRICT = 0.70;
        double LOCAL_HOLD_THRESHOLD = 0.20;
        double GLOBAL_COLOR_MAX = 0.35;
        double LOCAL_COLOR_MAX = 0.45;
        double MIN_RING_COVERAGE_LOCAL = 0.08;
        double MIN_RING_COVERAGE_GLOBAL = 0.10;
        double SUPER_STRICT_MATCH = 0.80; // Allow matches without ring if confidence is extremely high.

        int borderMarginX = (int)(minimap.width() * 0.08);
        int borderMarginY = (int)(minimap.height() * 0.08);
        double maxJumpPx = minimap.width() * 0.20; // Prevent large jumps unless confidence is very high.

        Mat ringMask = buildBlueRingMask(minimap);
        double ringDensity = Core.countNonZero(ringMask) / (double) (ringMask.rows() * ringMask.cols());
        boolean ringAvailable = ringDensity > 0.002;
        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_ring_mask.png", ringMask);
        }
        if (!ringAvailable) {
            System.out.printf("[TRACKER] Ring mask sparse (%.4f). Disabling ring gating for this frame.\n", ringDensity);
        }

        // ==========================================
        // PHASE 1: LOCAL ROI TRACKING (Has Memory)
        // ==========================================
        if (calibratedTemplate != null && lastKnownCenter != null) {
            int cx = (int)(calibratedTemplate.width() * 0.15);
            int cy = (int)(calibratedTemplate.height() * 0.15);
            int cw = (int)(calibratedTemplate.width() * 0.70);
            int ch = (int)(calibratedTemplate.height() * 0.70);
            Mat coreCalibrated = new Mat(calibratedTemplate, new Rect(cx, cy, cw, ch));

            // Create a tight 80x80 pixel search box around where she was LAST seen
            int searchRadius = 40;
            int roiX = (int) Math.max(0, lastKnownCenter.x - searchRadius);
            int roiY = (int) Math.max(0, lastKnownCenter.y - searchRadius);
            int roiW = (int) Math.min(minimap.width() - roiX, searchRadius * 2);
            int roiH = (int) Math.min(minimap.height() - roiY, searchRadius * 2);

            // Safety check to prevent OpenCV crashing if she runs to the absolute map edge
            if (roiW >= coreCalibrated.width() && roiH >= coreCalibrated.height()) {
                Rect searchRoi = new Rect(roiX, roiY, roiW, roiH);
                Mat localMinimap = new Mat(minimap, searchRoi);

                Mat result = new Mat();
                int matchMethod = chooseMatchMethod(coreCalibrated);
                Imgproc.matchTemplate(localMinimap, coreCalibrated, result, matchMethod);
                Core.MinMaxLocResult mmr = Core.minMaxLoc(result);

                // Because we are ONLY searching a tiny box, we can accept terrible scores caused by occlusion!
                if (mmr.maxVal > LOCAL_HOLD_THRESHOLD) {
                    Rect matchRect = new Rect((int)mmr.maxLoc.x, (int)mmr.maxLoc.y, coreCalibrated.width(), coreCalibrated.height());
                    Mat matchPatch = new Mat(localMinimap, matchRect);
                    double chromaDistance = getChromaticityDistance(coreCalibrated, matchPatch);
                    matchPatch.release();

                    double centerX = roiX + mmr.maxLoc.x + (coreCalibrated.width() / 2.0);
                    double centerY = roiY + mmr.maxLoc.y + (coreCalibrated.height() / 2.0);
                    double ringCoverage = ringAvailable
                            ? getRingCoverage(ringMask, centerX, centerY, coreCalibrated.width() * 0.55, coreCalibrated.width() * 1.10)
                            : 1.0;

                    if (chromaDistance <= LOCAL_COLOR_MAX && ringCoverage >= MIN_RING_COVERAGE_LOCAL) {
                        lastKnownCenter = new Point(centerX, centerY); // Update memory for the next frame

                        coreCalibrated.release();
                        result.release();
                        localMinimap.release();
                        ringMask.release();

                        drawDebugBox(minimap, centerX, centerY, calibratedTemplate.width(), calibratedTemplate.height(), new Scalar(0, 255, 0)); // Green Box
                        return new Point(centerX, centerY);
                    }
                }

                localMinimap.release();
                result.release();
            }

            // Target lost completely (teleported, died, or Viego covered 100% of her). Break the lock.
            coreCalibrated.release();
            calibratedTemplate.release();
            calibratedTemplate = null;
            // Keep lastKnownCenter to prevent random jumps during a weak global reacquire.
            System.out.println("[TRACKER] Local tracking broken. Target teleported or fully occluded. Forcing Global Sweep!");
        }

        // ==========================================
        // PHASE 2: GLOBAL SWEEP (No Memory)
        // ==========================================
        double bestScore = 0;
        double bestComposite = 0;
        Point bestCenter = null;
        Mat bestTemplateFull = null;

        for (double scale = 0.20; scale <= 1.60; scale += 0.05) {
            int targetWidth = (int) (championTemplate.width() * scale);
            int targetHeight = (int) (championTemplate.height() * scale);

            if (targetWidth < 16 || targetHeight < 16 || targetWidth > minimap.width() || targetHeight > minimap.height()) {
                continue;
            }

            Mat resizedTemplate = new Mat();
            Imgproc.resize(championTemplate, resizedTemplate, new org.opencv.core.Size(targetWidth, targetHeight), 0, 0, Imgproc.INTER_LINEAR);

            int cx = (int)(resizedTemplate.width() * 0.15);
            int cy = (int)(resizedTemplate.height() * 0.15);
            int cw = (int)(resizedTemplate.width() * 0.70);
            int ch = (int)(resizedTemplate.height() * 0.70);
            Mat coreTemplate = new Mat(resizedTemplate, new Rect(cx, cy, cw, ch));

            Mat result = new Mat();
            int matchMethod = chooseMatchMethod(coreTemplate);
            Imgproc.matchTemplate(minimap, coreTemplate, result, matchMethod);
            Core.MinMaxLocResult mmr = Core.minMaxLoc(result);

            if (mmr.maxVal > bestScore) {
                double centerX = mmr.maxLoc.x + (coreTemplate.width() / 2.0);
                double centerY = mmr.maxLoc.y + (coreTemplate.height() / 2.0);

                // Reject the borders for NEW locks to prevent grabbing UI elements
                if (centerX > borderMarginX && centerX < minimap.width() - borderMarginX &&
                        centerY > borderMarginY && centerY < minimap.height() - borderMarginY) {

                    // Reject pure black fog to avoid false positives
                    Rect matchRect = new Rect((int)mmr.maxLoc.x, (int)mmr.maxLoc.y, coreTemplate.width(), coreTemplate.height());
                    Mat matchPatch = new Mat(minimap, matchRect);
                    Scalar meanColor = Core.mean(matchPatch);
                    double brightness = (meanColor.val[0] + meanColor.val[1] + meanColor.val[2]) / 3.0;
                    double chromaDistance = getChromaticityDistance(coreTemplate, matchPatch);
                    matchPatch.release();

                    double ringCoverage = ringAvailable
                            ? getRingCoverage(ringMask, centerX, centerY, coreTemplate.width() * 0.55, coreTemplate.width() * 1.10)
                            : 1.0;
                    boolean ringOk = ringCoverage >= MIN_RING_COVERAGE_GLOBAL || mmr.maxVal >= SUPER_STRICT_MATCH || !ringAvailable;

                    if (brightness > 20.0 && chromaDistance <= GLOBAL_COLOR_MAX && ringOk) {
                        double composite = mmr.maxVal + (ringCoverage * 0.45);
                        if (lastKnownCenter != null) {
                            double jumpDist = Math.hypot(centerX - lastKnownCenter.x, centerY - lastKnownCenter.y);
                            composite -= (jumpDist / minimap.width()) * 0.25;
                        }

                        if (composite > bestComposite) {
                            bestScore = mmr.maxVal;
                            bestComposite = composite;
                            bestCenter = new Point(centerX, centerY);
                            if (bestTemplateFull != null) bestTemplateFull.release();
                            bestTemplateFull = resizedTemplate.clone();
                        }
                    }
                }
            }

            coreTemplate.release();
            resizedTemplate.release();
            result.release();
        }

        ringMask.release();

        // ==========================================
        // PHASE 3: VERIFY NEW GLOBAL LOCK
        // ==========================================
        if (bestScore > GLOBAL_ACQUIRE_THRESHOLD && bestCenter != null) {
            if (lastKnownCenter != null) {
                double jumpDist = Math.hypot(bestCenter.x - lastKnownCenter.x, bestCenter.y - lastKnownCenter.y);
                if (jumpDist > maxJumpPx && bestScore < GLOBAL_REACQUIRE_STRICT) {
                    System.out.printf("[TRACKER] Weak global reacquire (%.2f%%). Holding last known center.\n", (bestScore * 100));
                    if (bestTemplateFull != null) bestTemplateFull.release();
                    return lastKnownCenter;
                }
            }

            System.out.printf("[TRACKER] Global Target Acquired! Match: %.2f%%\n", (bestScore * 100));
            this.calibratedTemplate = bestTemplateFull;
            this.lastKnownCenter = bestCenter; // Save memory so Phase 1 takes over next frame!

            drawDebugBox(minimap, bestCenter.x, bestCenter.y, calibratedTemplate.width(), calibratedTemplate.height(), new Scalar(0, 165, 255)); // Orange Box
            return bestCenter;
        }

        if (bestTemplateFull != null) bestTemplateFull.release();
        System.out.printf("[TRACKER] Target missing globally. (Max Valid Score: %.2f%%)\n", (bestScore * 100));
        return null;
    }
    // --- Helper Methods ---

    // Calculates the Normalized Color Difference, effectively ignoring the Fog of War
    private double getChromaticityDistance(Mat template, Mat patch) {
        Scalar tempMean = Core.mean(template);
        // FIXED: Added .val to all array accesses
        double tempSum = tempMean.val[0] + tempMean.val[1] + tempMean.val[2];
        if (tempSum == 0) tempSum = 1.0; // Prevent divide by zero
        double tr = tempMean.val[2] / tempSum;
        double tg = tempMean.val[1] / tempSum;
        double tb = tempMean.val[0] / tempSum;

        Scalar patchMean = Core.mean(patch);
        // FIXED: Added .val to all array accesses
        double patchSum = patchMean.val[0] + patchMean.val[1] + patchMean.val[2];
        if (patchSum == 0) patchSum = 1.0;
        double pr = patchMean.val[2] / patchSum;
        double pg = patchMean.val[1] / patchSum;
        double pb = patchMean.val[0] / patchSum;

        return Math.abs(tr - pr) + Math.abs(tg - pg) + Math.abs(tb - pb);
    }

    private void drawDebugBox(Mat minimap, double centerX, double centerY, int width, int height, Scalar color) {
        if (WindowUtils.isWindowFocused("League of Legends")) {
            Mat debugMap = minimap.clone();
            Point topLeft = new Point(centerX - (width / 2.0), centerY - (height / 2.0));
            Point bottomRight = new Point(topLeft.x + width, topLeft.y + height);
            Imgproc.rectangle(debugMap, topLeft, bottomRight, color, 2);
            Imgcodecs.imwrite("debug_template_match.png", debugMap);
            debugMap.release();
        }
    }

    private void warnIfTemplateIsFlat(Mat template) {
        MatOfDouble mean = new MatOfDouble();
        MatOfDouble stddev = new MatOfDouble();
        Core.meanStdDev(template, mean, stddev);

        double meanVal = (mean.get(0, 0)[0] + mean.get(1, 0)[0] + mean.get(2, 0)[0]) / 3.0;
        double stdVal = (stddev.get(0, 0)[0] + stddev.get(1, 0)[0] + stddev.get(2, 0)[0]) / 3.0;

        if (meanVal < 10.0 || stdVal < 5.0) {
            System.out.printf("[TRACKER] Warning: Template looks flat/dark (mean=%.2f, std=%.2f). Matching may fail.\n", meanVal, stdVal);
        }

        mean.release();
        stddev.release();
    }

    private int chooseMatchMethod(Mat template) {
        MatOfDouble mean = new MatOfDouble();
        MatOfDouble stddev = new MatOfDouble();
        Core.meanStdDev(template, mean, stddev);

        double stdVal = (stddev.get(0, 0)[0] + stddev.get(1, 0)[0] + stddev.get(2, 0)[0]) / 3.0;
        mean.release();
        stddev.release();

        // CCOEFF_NORMED becomes unstable when the template is near-constant.
        return stdVal < 5.0 ? Imgproc.TM_CCORR_NORMED : Imgproc.TM_CCOEFF_NORMED;
    }

    private Mat captureScreen(Rectangle bounds) {
        BufferedImage rawImg = robot.createScreenCapture(bounds);

        BufferedImage bgrImg = new BufferedImage(bounds.width, bounds.height, BufferedImage.TYPE_3BYTE_BGR);
        Graphics2D g = bgrImg.createGraphics();
        g.drawImage(rawImg, 0, 0, null);
        g.dispose();

        byte[] pixels = ((DataBufferByte) bgrImg.getRaster().getDataBuffer()).getData();

        Mat mat = new Mat(bounds.height, bounds.width, CvType.CV_8UC3);
        mat.put(0, 0, pixels);

        return mat;
    }

    private Mat buildBlueRingMask(Mat minimap) {
        Mat hsv = new Mat();
        Imgproc.cvtColor(minimap, hsv, Imgproc.COLOR_BGR2HSV);

        Scalar lowerBlue = new Scalar(90, 90, 70);
        Scalar upperBlue = new Scalar(130, 255, 255);
        Mat mask = new Mat();
        Core.inRange(hsv, lowerBlue, upperBlue, mask);

        Mat kernel = Imgproc.getStructuringElement(Imgproc.MORPH_ELLIPSE, new org.opencv.core.Size(3, 3));
        Imgproc.morphologyEx(mask, mask, Imgproc.MORPH_CLOSE, kernel);

        hsv.release();
        kernel.release();
        return mask;
    }

    private double getRingCoverage(Mat ringMask, double centerX, double centerY, double innerRadius, double outerRadius) {
        int minX = (int) Math.max(0, Math.floor(centerX - outerRadius));
        int maxX = (int) Math.min(ringMask.width() - 1, Math.ceil(centerX + outerRadius));
        int minY = (int) Math.max(0, Math.floor(centerY - outerRadius));
        int maxY = (int) Math.min(ringMask.height() - 1, Math.ceil(centerY + outerRadius));

        double innerSq = innerRadius * innerRadius;
        double outerSq = outerRadius * outerRadius;
        double total = 0;
        double hits = 0;

        for (int y = minY; y <= maxY; y++) {
            for (int x = minX; x <= maxX; x++) {
                double dx = x - centerX;
                double dy = y - centerY;
                double distSq = (dx * dx) + (dy * dy);
                if (distSq >= innerSq && distSq <= outerSq) {
                    total += 1.0;
                    if (ringMask.get(y, x)[0] > 0) {
                        hits += 1.0;
                    }
                }
            }
        }

        return total > 0 ? (hits / total) : 0.0;
    }
}

package me.bedwarshurts.leagueproximitychat.position;

import me.bedwarshurts.leagueproximitychat.utils.LeagueConfigReader;
import me.bedwarshurts.leagueproximitychat.utils.RitoApiUtils;
import me.bedwarshurts.leagueproximitychat.utils.WindowUtils;
import org.opencv.core.*;
import org.opencv.core.Point;
import org.opencv.highgui.HighGui;
import org.opencv.imgcodecs.Imgcodecs;
import org.opencv.imgproc.Imgproc;
import org.opencv.imgproc.Moments;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferByte;

public class HybridPositionTracker {

    private Robot robot;
    private float userMinimapScale;

    private Mat championTemplate;
    private Mat calibratedTemplate = null;

    private Point lastKnownCenter = null;

    private static final float SCREEN_TO_MAP_RATIO = 0.05f;

    public static class TrackResult {
        public float x;
        public float y;
        public boolean isDead;

        public TrackResult(float x, float y, boolean isDead) {
            this.x = x;
            this.y = y;
            this.isDead = isDead;
        }
    }

    public HybridPositionTracker() {
        try {
            this.robot = new Robot();

            LeagueConfigReader.LeagueSettings settings = LeagueConfigReader.loadSettings();
            this.userMinimapScale = settings.minimapScale;

            this.championTemplate = AutoTemplateLoader.autoLoadChampionTemplate();
            if (championTemplate != null) {
                HighGui.imshow("Champion Template", championTemplate);
                HighGui.waitKey(0);

                Imgcodecs.imwrite("debug_template.png", championTemplate);
                warnIfTemplateIsFlat(championTemplate);
            }

            if (this.championTemplate == null) {
                System.err.println("[TRACKER] CRITICAL: Failed to load champion template.");
            }

        } catch (AWTException e) {
            System.err.println("[TRACKER] Failed to initialize Java Robot API");
            e.printStackTrace();
        }
    }

    public TrackResult trackPlayerPosition() {
        boolean isDead = checkDeathState();

        java.awt.Rectangle gameBounds = WindowUtils.getGameWindowBounds("League of Legends (TM) Client");

        if (gameBounds == null) {
            return new TrackResult(50f, 50f, isDead);
        }

        double baseMapPercent = 0.1425;
        int perfectMapSize = (int) (gameBounds.height * baseMapPercent * userMinimapScale);

        java.awt.Rectangle minimapBounds = new java.awt.Rectangle(
                gameBounds.x + gameBounds.width - perfectMapSize,
                gameBounds.y + gameBounds.height - perfectMapSize,
                perfectMapSize,
                perfectMapSize
        );

        Mat fullScreenMat = captureScreen(gameBounds);
        Mat minimapMat = captureScreen(minimapBounds);

        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_screen.png", fullScreenMat);
            Imgcodecs.imwrite("debug_minimap.png", minimapMat);
        }

        Point healthBarCenter = locateSelfHealthBar(fullScreenMat);

        if (healthBarCenter != null) {
            float offsetX = (float) (healthBarCenter.x - (gameBounds.width / 2.0));
            float offsetY = (float) (healthBarCenter.y - (gameBounds.height / 2.0));

            Point cameraMapCenter = locateMinimapCameraBox(minimapMat);

            float finalX = (float) cameraMapCenter.x + (offsetX * SCREEN_TO_MAP_RATIO);
            float finalY = (float) cameraMapCenter.y + (offsetY * SCREEN_TO_MAP_RATIO);

            float invertedY = 100f - ((finalY / minimapBounds.height) * 100f);

            return new TrackResult((finalX / minimapBounds.width) * 100f, invertedY, isDead);

        } else if (championTemplate != null) {
            Point champMapCenter = locateChampionViaTemplate(minimapMat);

            if (champMapCenter != null) {
                float finalX = (float) champMapCenter.x;
                float finalY = (float) champMapCenter.y;

                float invertedY = 100f - ((finalY / minimapBounds.height) * 100f);

                return new TrackResult((finalX / minimapBounds.width) * 100f, invertedY, isDead);
            }
        }

        return new TrackResult(50f, 50f, isDead);
    }

    private boolean checkDeathState() {
        String localSummonerName = RitoApiUtils.getLocalSummonerName();

        if (localSummonerName != null) {
            String playerListJson = RitoApiUtils.fetchAPI("https://127.0.0.1:2999/liveclientdata/playerlist");
            if (playerListJson != null) {
                int nameIdx = playerListJson.indexOf("\"" + localSummonerName + "\"");
                if (nameIdx != -1) {
                    int blockStart = playerListJson.lastIndexOf("\"championName\":", nameIdx);
                    if (blockStart != -1) {
                        int blockEnd = playerListJson.indexOf("\"championName\":", blockStart + 15);
                        if (blockEnd == -1) {
                            blockEnd = playerListJson.length();
                        }

                        String playerBlock = playerListJson.substring(blockStart, blockEnd).replaceAll("\\s+", "");
                        return playerBlock.contains("\"isDead\":true");
                    }
                }
            }
        }
        return false;
    }

    private Point locateSelfHealthBar(Mat screen) {
        Mat hsv = new Mat();
        Imgproc.cvtColor(screen, hsv, Imgproc.COLOR_BGR2HSV);

        Scalar lowerYellow = new Scalar(22, 140, 200);
        Scalar upperYellow = new Scalar(26, 255, 255);

        Mat mask = new Mat();
        Core.inRange(hsv, lowerYellow, upperYellow, mask);

        int hudTopY = (int) (screen.height() * 0.75);
        Imgproc.rectangle(mask, new Point(0, hudTopY), new Point(screen.width(), screen.height()), new Scalar(0), -1);

        Imgproc.rectangle(mask, new Point(screen.width() * 0.85, 0), new Point(screen.width(), screen.height() * 0.10), new Scalar(0), -1);

        Mat openKernel = Imgproc.getStructuringElement(Imgproc.MORPH_RECT, new org.opencv.core.Size(3, 3));
        Imgproc.morphologyEx(mask, mask, Imgproc.MORPH_OPEN, openKernel);
        openKernel.release();

        Mat closeKernel = Imgproc.getStructuringElement(Imgproc.MORPH_RECT, new org.opencv.core.Size(11, 1));
        Imgproc.morphologyEx(mask, mask, Imgproc.MORPH_CLOSE, closeKernel);
        closeKernel.release();

        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_health_mask.png", mask);
        }

        java.util.List<MatOfPoint> contours = new java.util.ArrayList<>();
        Mat hierarchy = new Mat();
        Imgproc.findContours(mask, contours, hierarchy, Imgproc.RETR_EXTERNAL, Imgproc.CHAIN_APPROX_SIMPLE);

        Rect bestBar = null;
        double bestDistance = Double.MAX_VALUE;

        double minHeight = screen.height() * 0.003;
        double maxHeight = screen.height() * 0.020;
        double minWidth = screen.width() * 0.008;

        for (MatOfPoint contour : contours) {
            Rect rect = Imgproc.boundingRect(contour);
            double pixelArea = Imgproc.contourArea(contour);

            if (rect.height >= minHeight && rect.height <= maxHeight && rect.width >= minWidth) {

                double extent = pixelArea / (double) (rect.width * rect.height);
                double aspectRatio = rect.width / (double) rect.height;

                if (extent > 0.75 && aspectRatio > 2.5) {

                    double centerX = rect.x + (rect.width / 2.0);
                    double centerY = rect.y + (rect.height / 2.0);

                    double distToCenter = Math.pow(centerX - (screen.width() / 2.0), 2) + Math.pow(centerY - (screen.height() / 2.0), 2);

                    if (distToCenter < bestDistance) {
                        bestDistance = distToCenter;
                        bestBar = rect;
                    }
                }
            }
        }

        if (bestBar != null) {
            return new Point(bestBar.x + (bestBar.width / 2.0), bestBar.y + (bestBar.height / 2.0));
        }

        return null;
    }

    private Point locateMinimapCameraBox(Mat minimap) {
        Mat gray = new Mat();
        Imgproc.cvtColor(minimap, gray, Imgproc.COLOR_BGR2GRAY);

        Mat thresholded = new Mat();
        Imgproc.threshold(gray, thresholded, 240, 255, Imgproc.THRESH_BINARY);

        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_camera_mask.png", thresholded);
        }

        Moments moments = Imgproc.moments(thresholded);
        if (moments.get_m00() > 0) {
            int x = (int) (moments.get_m10() / moments.get_m00());
            int y = (int) (moments.get_m01() / moments.get_m00());
            return new Point(x, y);
        }
        return new Point(minimap.width() / 2.0, minimap.height() / 2.0);
    }


    private Point locateChampionViaTemplate(Mat minimap) {
        System.out.println("[TRACKER] Primary HP bar lost. Running Stateful ROI Tracker...");

        // GLOBAL is very strict to prevent locking onto mud.
        // LOCAL is extremely loose to survive Viego sitting on top of her.
        double GLOBAL_ACQUIRE_THRESHOLD = 0.55;
        double GLOBAL_REACQUIRE_STRICT = 0.70;
        double LOCAL_HOLD_THRESHOLD = 0.20;
        double GLOBAL_COLOR_MAX = 0.35;
        double LOCAL_COLOR_MAX = 0.45;
        double MIN_RING_COVERAGE_LOCAL = 0.08;
        double MIN_RING_COVERAGE_GLOBAL = 0.10;
        double SUPER_STRICT_MATCH = 0.80; // Allow matches without ring if confidence is extremely high.

        int borderMarginX = (int)(minimap.width() * 0.08);
        int borderMarginY = (int)(minimap.height() * 0.08);
        double maxJumpPx = minimap.width() * 0.20; // Prevent large jumps unless confidence is very high.

        Mat ringMask = buildBlueRingMask(minimap);
        double ringDensity = Core.countNonZero(ringMask) / (double) (ringMask.rows() * ringMask.cols());
        boolean ringAvailable = ringDensity > 0.002;
        if (WindowUtils.isWindowFocused("League of Legends")) {
            Imgcodecs.imwrite("debug_ring_mask.png", ringMask);
        }
        if (!ringAvailable) {
            System.out.printf("[TRACKER] Ring mask sparse (%.4f). Disabling ring gating for this frame.\n", ringDensity);
        }

        // ==========================================
        // PHASE 1: LOCAL ROI TRACKING (Has Memory)
        // ==========================================
        if (calibratedTemplate != null && lastKnownCenter != null) {
            int cx = (int)(calibratedTemplate.width() * 0.15);
            int cy = (int)(calibratedTemplate.height() * 0.15);
            int cw = (int)(calibratedTemplate.width() * 0.70);
            int ch = (int)(calibratedTemplate.height() * 0.70);
            Mat coreCalibrated = new Mat(calibratedTemplate, new Rect(cx, cy, cw, ch));

            // Create a tight 80x80 pixel search box around where she was LAST seen
            int searchRadius = 40;
            int roiX = (int) Math.max(0, lastKnownCenter.x - searchRadius);
            int roiY = (int) Math.max(0, lastKnownCenter.y - searchRadius);
            int roiW = (int) Math.min(minimap.width() - roiX, searchRadius * 2);
            int roiH = (int) Math.min(minimap.height() - roiY, searchRadius * 2);

            // Safety check to prevent OpenCV crashing if she runs to the absolute map edge
            if (roiW >= coreCalibrated.width() && roiH >= coreCalibrated.height()) {
                Rect searchRoi = new Rect(roiX, roiY, roiW, roiH);
                Mat localMinimap = new Mat(minimap, searchRoi);

                Mat result = new Mat();
                int matchMethod = chooseMatchMethod(coreCalibrated);
                Imgproc.matchTemplate(localMinimap, coreCalibrated, result, matchMethod);
                Core.MinMaxLocResult mmr = Core.minMaxLoc(result);

                double matchScore = (matchMethod == Imgproc.TM_SQDIFF_NORMED) ? (1.0 - mmr.minVal) : mmr.maxVal;
                Point matchLoc = (matchMethod == Imgproc.TM_SQDIFF_NORMED) ? mmr.minLoc : mmr.maxLoc;

                // Because we are ONLY searching a tiny box, we can accept terrible scores caused by occlusion!
                if (matchScore > LOCAL_HOLD_THRESHOLD) {
                    Rect matchRect = new Rect((int)matchLoc.x, (int)matchLoc.y, coreCalibrated.width(), coreCalibrated.height());
                    Mat matchPatch = new Mat(localMinimap, matchRect);
                    double chromaDistance = getChromaticityDistance(coreCalibrated, matchPatch);
                    matchPatch.release();

                    double centerX = roiX + matchLoc.x + (coreCalibrated.width() / 2.0);
                    double centerY = roiY + matchLoc.y + (coreCalibrated.height() / 2.0);
                    double ringCoverage = ringAvailable
                            ? getRingCoverage(ringMask, centerX, centerY, coreCalibrated.width() * 0.55, coreCalibrated.width() * 1.10)
                            : 1.0;

                    if (chromaDistance <= LOCAL_COLOR_MAX && ringCoverage >= MIN_RING_COVERAGE_LOCAL) {
                        lastKnownCenter = new Point(centerX, centerY); // Update memory for the next frame

                        coreCalibrated.release();
                        result.release();
                        localMinimap.release();
                        ringMask.release();

                        drawDebugBox(minimap, centerX, centerY, calibratedTemplate.width(), calibratedTemplate.height(), new Scalar(0, 255, 0)); // Green Box
                        return new Point(centerX, centerY);
                    }
                }

                localMinimap.release();
                result.release();
            }

            // Target lost completely (teleported, died, or Viego covered 100% of her). Break the lock.
            coreCalibrated.release();
            calibratedTemplate.release();
            calibratedTemplate = null;
            // Keep lastKnownCenter to prevent random jumps during a weak global reacquire.
            System.out.println("[TRACKER] Local tracking broken. Target teleported or fully occluded. Forcing Global Sweep!");
        }

        // ==========================================
        // PHASE 2: GLOBAL SWEEP (No Memory)
        // ==========================================
        double bestScore = 0;
        double bestComposite = 0;
        Point bestCenter = null;
        Mat bestTemplateFull = null;

        for (double scale = 0.20; scale <= 1.60; scale += 0.05) {
            int targetWidth = (int) (championTemplate.width() * scale);
            int targetHeight = (int) (championTemplate.height() * scale);

            if (targetWidth < 16 || targetHeight < 16 || targetWidth > minimap.width() || targetHeight > minimap.height()) {
                continue;
            }

            Mat resizedTemplate = new Mat();
            Imgproc.resize(championTemplate, resizedTemplate, new org.opencv.core.Size(targetWidth, targetHeight), 0, 0, Imgproc.INTER_LINEAR);

            int cx = (int)(resizedTemplate.width() * 0.15);
            int cy = (int)(resizedTemplate.height() * 0.15);
            int cw = (int)(resizedTemplate.width() * 0.70);
            int ch = (int)(resizedTemplate.height() * 0.70);
            Mat coreTemplate = new Mat(resizedTemplate, new Rect(cx, cy, cw, ch));

            Mat result = new Mat();
            int matchMethod = chooseMatchMethod(coreTemplate);
            Imgproc.matchTemplate(minimap, coreTemplate, result, matchMethod);
            Core.MinMaxLocResult mmr = Core.minMaxLoc(result);

            double matchScore = (matchMethod == Imgproc.TM_SQDIFF_NORMED) ? (1.0 - mmr.minVal) : mmr.maxVal;
            Point matchLoc = (matchMethod == Imgproc.TM_SQDIFF_NORMED) ? mmr.minLoc : mmr.maxLoc;

            if (matchScore > bestScore) {
                double centerX = matchLoc.x + (coreTemplate.width() / 2.0);
                double centerY = matchLoc.y + (coreTemplate.height() / 2.0);

                // Reject the borders for NEW locks to prevent grabbing UI elements
                if (centerX > borderMarginX && centerX < minimap.width() - borderMarginX &&
                        centerY > borderMarginY && centerY < minimap.height() - borderMarginY) {

                    // Reject pure black fog to avoid false positives
                    Rect matchRect = new Rect((int)matchLoc.x, (int)matchLoc.y, coreTemplate.width(), coreTemplate.height());
                    Mat matchPatch = new Mat(minimap, matchRect);
                    Scalar meanColor = Core.mean(matchPatch);
                    double brightness = (meanColor.val[0] + meanColor.val[1] + meanColor.val[2]) / 3.0;
                    double chromaDistance = getChromaticityDistance(coreTemplate, matchPatch);
                    matchPatch.release();

                    double ringCoverage = ringAvailable
                            ? getRingCoverage(ringMask, centerX, centerY, coreTemplate.width() * 0.55, coreTemplate.width() * 1.10)
                            : 1.0;
                    boolean ringOk = ringCoverage >= MIN_RING_COVERAGE_GLOBAL || matchScore >= SUPER_STRICT_MATCH || !ringAvailable;

                    if (brightness > 20.0 && chromaDistance <= GLOBAL_COLOR_MAX && ringOk) {
                        double composite = matchScore + (ringCoverage * 0.45);
                        if (lastKnownCenter != null) {
                            double jumpDist = Math.hypot(centerX - lastKnownCenter.x, centerY - lastKnownCenter.y);
                            composite -= (jumpDist / minimap.width()) * 0.25;
                        }

                        if (composite > bestComposite) {
                            bestScore = matchScore;
                            bestComposite = composite;
                            bestCenter = new Point(centerX, centerY);
                            if (bestTemplateFull != null) bestTemplateFull.release();
                            bestTemplateFull = resizedTemplate.clone();
                        }
                    }
                }
            }

            coreTemplate.release();
            resizedTemplate.release();
            result.release();
        }

        ringMask.release();

        // ==========================================
        // PHASE 3: VERIFY NEW GLOBAL LOCK
        // ==========================================
        if (bestScore > GLOBAL_ACQUIRE_THRESHOLD && bestCenter != null) {
            if (lastKnownCenter != null) {
                double jumpDist = Math.hypot(bestCenter.x - lastKnownCenter.x, bestCenter.y - lastKnownCenter.y);
                if (jumpDist > maxJumpPx && bestScore < GLOBAL_REACQUIRE_STRICT) {
                    System.out.printf("[TRACKER] Weak global reacquire (%.2f%%). Holding last known center.\n", (bestScore * 100));
                    if (bestTemplateFull != null) bestTemplateFull.release();
                    return lastKnownCenter;
                }
            }

            System.out.printf("[TRACKER] Global Target Acquired! Match: %.2f%%\n", (bestScore * 100));
            this.calibratedTemplate = bestTemplateFull;
            this.lastKnownCenter = bestCenter; // Save memory so Phase 1 takes over next frame!

            drawDebugBox(minimap, bestCenter.x, bestCenter.y, calibratedTemplate.width(), calibratedTemplate.height(), new Scalar(0, 165, 255)); // Orange Box
            return bestCenter;
        }

        if (bestTemplateFull != null) bestTemplateFull.release();
        System.out.printf("[TRACKER] Target missing globally. (Max Valid Score: %.2f%%)\n", (bestScore * 100));
        return null;
    }
    // --- Helper Methods ---

    // Calculates the Normalized Color Difference, effectively ignoring the Fog of War
    private double getChromaticityDistance(Mat template, Mat patch) {
        Scalar tempMean = Core.mean(template);
        // FIXED: Added .val to all array accesses
        double tempSum = tempMean.val[0] + tempMean.val[1] + tempMean.val[2];
        if (tempSum == 0) tempSum = 1.0; // Prevent divide by zero
        double tr = tempMean.val[2] / tempSum;
        double tg = tempMean.val[1] / tempSum;
        double tb = tempMean.val[0] / tempSum;

        Scalar patchMean = Core.mean(patch);
        // FIXED: Added .val to all array accesses
        double patchSum = patchMean.val[0] + patchMean.val[1] + patchMean.val[2];
        if (patchSum == 0) patchSum = 1.0;
        double pr = patchMean.val[2] / patchSum;
        double pg = patchMean.val[1] / patchSum;
        double pb = patchMean.val[0] / patchSum;

        return Math.abs(tr - pr) + Math.abs(tg - pg) + Math.abs(tb - pb);
    }

    private void drawDebugBox(Mat minimap, double centerX, double centerY, int width, int height, Scalar color) {
        if (WindowUtils.isWindowFocused("League of Legends")) {
            Mat debugMap = minimap.clone();
            Point topLeft = new Point(centerX - (width / 2.0), centerY - (height / 2.0));
            Point bottomRight = new Point(topLeft.x + width, topLeft.y + height);
            Imgproc.rectangle(debugMap, topLeft, bottomRight, color, 2);
            Imgcodecs.imwrite("debug_template_match.png", debugMap);
            debugMap.release();
        }
    }

    private void warnIfTemplateIsFlat(Mat template) {
        MatOfDouble mean = new MatOfDouble();
        MatOfDouble stddev = new MatOfDouble();
        Core.meanStdDev(template, mean, stddev);

        double meanVal = (mean.get(0, 0)[0] + mean.get(1, 0)[0] + mean.get(2, 0)[0]) / 3.0;
        double stdVal = (stddev.get(0, 0)[0] + stddev.get(1, 0)[0] + stddev.get(2, 0)[0]) / 3.0;

        if (meanVal < 10.0 || stdVal < 5.0) {
            System.out.printf("[TRACKER] Warning: Template looks flat/dark (mean=%.2f, std=%.2f). Matching may fail.\n", meanVal, stdVal);
        }

        mean.release();
        stddev.release();
    }

    private int chooseMatchMethod(Mat template) {
        MatOfDouble mean = new MatOfDouble();
        MatOfDouble stddev = new MatOfDouble();
        Core.meanStdDev(template, mean, stddev);

        double stdVal = (stddev.get(0, 0)[0] + stddev.get(1, 0)[0] + stddev.get(2, 0)[0]) / 3.0;
        mean.release();
        stddev.release();

        // CCOEFF_NORMED becomes unstable when the template is near-constant.
        return stdVal < 5.0 ? Imgproc.TM_SQDIFF_NORMED : Imgproc.TM_CCOEFF_NORMED;
    }

    private Mat captureScreen(Rectangle bounds) {
        BufferedImage rawImg = robot.createScreenCapture(bounds);

        BufferedImage bgrImg = new BufferedImage(bounds.width, bounds.height, BufferedImage.TYPE_3BYTE_BGR);
        Graphics2D g = bgrImg.createGraphics();
        g.drawImage(rawImg, 0, 0, null);
        g.dispose();

        byte[] pixels = ((DataBufferByte) bgrImg.getRaster().getDataBuffer()).getData();

        Mat mat = new Mat(bounds.height, bounds.width, CvType.CV_8UC3);
        mat.put(0, 0, pixels);

        return mat;
    }

    private Mat buildBlueRingMask(Mat minimap) {
        Mat hsv = new Mat();
        Imgproc.cvtColor(minimap, hsv, Imgproc.COLOR_BGR2HSV);

        Scalar lowerBlue = new Scalar(90, 90, 70);
        Scalar upperBlue = new Scalar(130, 255, 255);
        Mat mask = new Mat();
        Core.inRange(hsv, lowerBlue, upperBlue, mask);

        Mat kernel = Imgproc.getStructuringElement(Imgproc.MORPH_ELLIPSE, new org.opencv.core.Size(3, 3));
        Imgproc.morphologyEx(mask, mask, Imgproc.MORPH_CLOSE, kernel);

        hsv.release();
        kernel.release();
        return mask;
    }

    private double getRingCoverage(Mat ringMask, double centerX, double centerY, double innerRadius, double outerRadius) {
        int minX = (int) Math.max(0, Math.floor(centerX - outerRadius));
        int maxX = (int) Math.min(ringMask.width() - 1, Math.ceil(centerX + outerRadius));
        int minY = (int) Math.max(0, Math.floor(centerY - outerRadius));
        int maxY = (int) Math.min(ringMask.height() - 1, Math.ceil(centerY + outerRadius));

        double innerSq = innerRadius * innerRadius;
        double outerSq = outerRadius * outerRadius;
        double total = 0;
        double hits = 0;

        for (int y = minY; y <= maxY; y++) {
            for (int x = minX; x <= maxX; x++) {
                double dx = x - centerX;
                double dy = y - centerY;
                double distSq = (dx * dx) + (dy * dy);
                if (distSq >= innerSq && distSq <= outerSq) {
                    total += 1.0;
                    if (ringMask.get(y, x)[0] > 0) {
                        hits += 1.0;
                    }
                }
            }
        }

        return total > 0 ? (hits / total) : 0.0;
    }
}
